const payload = $input.first().json.payload || $input.first().json;
const attendee = (payload.attendees && payload.attendees[0]) || {};
const email = attendee.email || '';
const domain = email.includes('@') ? email.split('@')[1] : '';
return [{ json: { name: attendee.name || 'Guest', email, domain, eventTitle: payload.title || 'Strategy Session', startTime: payload.startTime || '', notes: payload.additionalNotes || '' } }];
